(68, 36, 'DKCzxaDtNre', 'video', 'https://scontent-bos5-1.cdninstagram.com/o1/v/t2/f2/m86/AQP94yqdy29QqVIJdioG1upTYj6lI_xlBznAYtWK2_aLzVXZFw_RVZBT534tgqOKsDUDszuX46c_H17GCvMuhITb2S_Tn42c2in2HyI.mp4?_nc_cat=103&_nc_sid=5e9851&_nc_ht=scontent-bos5-1.cdninstagram.com&_nc_ohc=wgjRV5cow4QQ7kNvwGguNxN&efg=eyJ2ZW5jb2RlX3RhZyI6Inhwdl9wcm9ncmVzc2l2ZS5JTlNUQUdSQU0uQ0xJUFMuQzMuNzIwLmRhc2hfYmFzZWxpbmVfMV92MSIsInhwdl9hc3NldF9pZCI6MjQwNzg0MTQ0NjI1NjI4MiwiYXNzZXRfYWdlX2RheXMiOjE5MywidmlfdXNlY2FzZV9pZCI6MTAwOTksImR1cmF0aW9uX3MiOjMwLCJ1cmxnZW5fc291cmNlIjoid3d3In0%3D&ccb=17-1&vs=873d6c89d01bd4&_nc_-rdLxqfvnGBJkYXNoX2Jhc2VsaW5lXzFfdjERAHX-B2XmnQEA&_nc_gid=zVGSjlP6yopGd9YftrTLKA&_nc_zt=28&oh=00_Afl9Dc95aT3IFxDd53uhHeRxxCMjE_5KKQ9d-mIVB2LjUA&oe=69323EA0', '‼️شمارو به دنیایی از تخصص دعوت میکنم🥰♥️\nاینجا در ورکشاپ تخصصی عروس مدل های تکنیکالی مثله:\n✨ عروس لبنانی\n✨ عروس مولاژی\n✨ بالاتنه ویکتوریایی\nاموزش میبینی تا به دنیا جدید حرفه ای ها پا بزاری😍\nو یادمیگیری چطور:⁉️\n✅ لباس عروس سبک با زیرساز ویکتوریایی بدوزی\n✅ یادمیگیر فنردوزی طاقدیسی رو چطور برای زیرساز گنبدی استفاده کنی\n✅ یادمیگیری لانگ باکس بدوزی اما سبک و تکنیکال بدون دغدغه شکستن فنر ها و گریت های کثیف و سوله و بینهایت تکنیک تخصصی که…\n‼️ با افتخار برای اولین بار در ایران درحال تدریس اون ها هستم چون ترکیبی از تجربه و انالیز های منه🥹♥️\nو قراره بعد این ورکشاپ نه فقط ۳ مدل بلکه ۱۰ ها مدل رو به سادگی انالیر کنی و بهتر از خود مدل بدوزی چون این تخصص منه که به شما چیزی رو اموزش بدم که خروجی کارتو زیر و رو کنه♥️😍\n.\nاگه تمایل داری اطلاعات کامل رو دریافت کنی کلمه “ ورکشاپ” رو کامنت کن‼️☺️\n.\n#عروس #کلاس_تخصصی #مزون_عروس', '[\"#\\u0639\\u0631\\u0648\\u0633\",\"#\\u06a9\\u0644\\u0627\\u0633_\\u062a\\u062e\\u0635\\u0635\\u06cc\",\"#\\u0645\\u0632\\u0648\\u0646_\\u0639\\u0631\\u0648\\u0633\"]', 3, 2005, 889, 44964, 0, 0, 30.721000671387, NULL, '2025-05-24 17:10:10', 816, 0, '2025-12-03 14:38:11', '2025-12-03 14:38:11'),
