(71, 36, 'DOTRnG7gqkg', 'video', 'https://scontent-lax3-1.cdninstagram.com/o1/v/t2/f2/m86/AQOBOTXURUTJZWGXWecX9K54PH66-VvspiQK8RiLdrw3nN1K1lW3-TaAL7xM54cvKi6OsYzqPyu8yU8HcSRhKvFujlw8CTruZf1_m_I.mp4?_nc_cat=108&_nc_sid=5e9851&_nc_ht=scontent-lax3-1.cdninstagram.com&_nc_ohc=FaRAuXkriEkQ7kNvwFOgDCR&efg=eyJ2ZW5jb2RlX3RhZyI6Inhwdl9wcm9ncmVzc2l2ZS5JTlNUQUdSQU0uQ0xJUFMuQzMuNzIwLmRhc2hfYmFzZWxpbmVfMV92MSIsInhwdl9hc3NldF9pZCI6MTI0NDE2MTk0NDEzMDI5OCwiYXNzZXRfYWdlX2RheXMiOjg5LCJ2aV91c2VjYXNlX2lkIjoxMDA5OSwiZHVyYXRpb25fcyI6MjMsInVybGdlbl9zb3VyY2UiOiJ3d3cifQ%3D%3D&ccb=17-1&vs=39db1642c081ebaf&_nc_vs=HBksFQIYUmlnX3hwdl9yZWVsc19wZXJtYW5lbnRfc3JfcHJvZC9CNzRFOTc1Njg0REJCQUE5MEJFQ0UzQ0M3NzU4RTdBMV92aWRlb19kYXNoaW5pdC5tcDQVAALIARIAFQIYOnBhc3N0aHJvdWdoX2V2ZXJzdG9yZS9HS25CUnlCem9iV0pRcmtDQUVjd0sxTms2cVk3YnFfRUFBQUYVAgLIARIAKAAYABsCiAd1c2Vfb2lsATEScHJvZ3Jlc3NpdmVfcmVjaXBlATEVAAAm9MvI6-DjtQQVAigCQzMsF0A3btkWhysCGBJkYXNoX2Jhc2VsaW5lXzFfdjERAHX-B2XmnQEA&_nc_gid=K4oLaVRtGQDOofUhYQ1U4Q&_nc_zt=28&oh=00_AfmbVplqZjirvFmkM8AOfZNa_ujRNyH5fRoR8nSpiCteVA&oe=6934CEF5', 'وقتی لباس عروس فقط پوشیدنی نیست، بلکه خاطره‌ساز میشه...\nما در مزون و آکادمی …، هر لباس رو مثل یک اثر هنری خلق می‌کنیم:\n💍 دوخت تخصصی لباس‌های عروس، فرمالیته، شب و مجلسی\n🎓 آموزش تخصصی طراحی و دوخت برای علاقه‌مندان حرفه‌ای\n🪡 لاین ویژه پارچه، دانتل و متریال عروس برای هنرجوها و مزون‌دارها\n\nاینجا جاییه که رؤیاها با نخ و سوزن شکل می‌گیرن 🌸\nفقط کافیه اینجا باشی 🥰\n#لباس_عروس\n#لباس_مجلسی\n#مزون\n#مزون_لباس\n#عروس\n#مزون_عروس\n#خیاطی_لباس_عروس\n\n📌 هشتگ‌های انگلیسی\n\n#bridal\n#weddingdress\n#weddinginspiration\n#eveningdress\n#partydress\n#fashion\n#handmade\n#couture', '[\"#\\u0644\\u0628\\u0627\\u0633_\\u0639\\u0631\\u0648\\u0633\",\"#\\u0644\\u0628\\u0627\\u0633_\\u0645\\u062c\\u0644\\u0633\\u06cc\",\"#\\u0645\\u0632\\u0648\\u0646\",\"#\\u0645\\u0632\\u0648\\u0646_\\u0644\\u0628\\u0627\\u0633\",\"#\\u0639\\u0631\\u0648\\u0633\",\"#\\u0645\\u0632\\u0648\\u0646_\\u0639\\u0631\\u0648\\u0633\",\"#\\u062e\\u06cc\\u0627\\u0637\\u06cc_\\u0