(81, 36, 'DQ5_t_ajMDL', 'video', 'https://scontent-sjc6-1.cdninstagram.com/o1/v/t2/f2/m86/AQNtmbBGIfEsPqlJx5JkiZylX8Ka8T-XXNdjB9sTt6WqHolvEDeBP3urYjEtUj4oqkQWb26lR7EArpkuv6IfwUr0OLioGUUB2qzedQs.mp4?_nc_cat=111&_nc_sid=5e9851&_nc_ht=scontent-sjc6-1.cdninstagram.com&_nc_ohc=pruu-Z14EdUQ7kNvwFcSDE5&efg=eyJ2ZW5jb2RlX3RhZyI6Inhwdl9wcm9ncmVzc2l2ZS5JTlNUQUdSQU0uQ0xJUFMuQzMuNzIwLmRhc2hfYmFzZWxpbmVfMV92MSIsInhwdl9hc3NldF9pZCI6MTUyOTU1MzE5MTUyOTA1MiwiYXNzZXRfYWdlX2RheXMiOjI0LCJ2aV91c2VjYXNlX2lkIjoxMDA5OSwiZHVyYXRpb25fcyI6OCwidXJsZ2VuX3NvdXJjZSI6Ind3dyJ9&ccb=17-1&vs=5c405dc787ee9938&_nc_-B2XmnQEA&_nc_gid=paB_IoG6hSLhsVWwbeCWYQ&_nc_zt=28&oh=00_Afnh4B-LaFY8unHxi_c722ln_E7WLXyBAkPDzweQ-S6PMg&oe=6934CEE0', '⁨	⁨	⁨	دلم رفت🫠🥹\n\nسفارش یه مشتری خوش سلیقه👌😍\n\nاین لباس خوشگلمون رو میتونید طبق سایز ‌‌و رنگ دلخواهتون سفارش بدید🤗💖\n\nتو‌ مزون نی نی آناسا زیباترین لباس ها رو‌ با بهترین کیفیت ‌و مناسب ترین قیمت تقدیمتون می‌کنیم👌🤗\n\n‪‪@ninianasa‬‪@ninianasa‬sa‬sa\n\n#پیراهن_مجلسی #لباس_دخترانه #نی_نی_آناسا #لباس_پرنسسی #دخترونه\n#لباس_پرنسسی #لباس_کودک #لباس_دخترانه #آناسا #لباس_خاص #استایل_پرنسسی #دوخت_دست_ساز⁩⁩', '[\"#\\u067e\\u06cc\\u0631\\u0627\\u0647\\u0646_\\u0645\\u062c\\u0644\\u0633\\u06cc\",\"#\\u0644\\u0628\\u0627\\u0633_\\u062f\\u062e\\u062a\\u0631\\u0627\\u0646\\u0647\",\"#\\u0646\\u06cc_\\u0646\\u06cc_\\u0622\\u0646\\u0627\\u0633\\u0627\",\"#\\u0644\\u0628\\u0627\\u0633_\\u067e\\u0631\\u0646\\u0633\\u0633\\u06cc\",\"#\\u062f\\u062e\\u062a\\u0631\\u0648\\u0646\\u0647\",\"#\\u0644\\u0628\\u0627\\u0633_\\u067e\\u0631\\u0646\\u0633\\u0633\\u06cc\",\"#\\u0644\\u0628\\u0627\\u0633_\\u06a9\\u0648\\u062f\\u06a9\",\"#\\u0644\\u0628\\u0627\\u0633_\\u062f\\u062e\\u062a\\u0631\\u0627\\u0646\\u0647\",\"#\\u0622\\u0646\\u0627\\u0633\\u0627\",\"#\\u0644\\u0628\\u0627\\u0633_\\u062e\\u0627\\u0635\",\"#\\u0627\\u0633\\u062a\\u0627\\u06cc\\u0644_\\u067e\\u0631\\u0646\\u0633\\u0633\\u06cc\",\"#\\u062f\\u0648\\u062e\\u062a_\\u062f\\u0633\\u062a_\\u0633\\u0627\\u0632\"]', 12, 19333, 547, 614887, 0,