\n۰۹۳۷۳۳۹۹۵۰۴\n\nشعبه ۶:\nجاده طرقبه، نبش امام رضا ۱۹\n#شله_مشهدی  #خوشمزه #شله #شله_درباری\n#food⁩', '\"[\\\"#\\\\u0634\\\\u0644\\\\u0647_\\\\u0645\\\\u0634\\\\u0647\\\\u062f\\\\u06cc\\\",\\\"#\\\\u062e\\\\u0648\\\\u0634\\\\u0645\\\\u0632\\\\u0647\\\",\\\"#\\\\u0634\\\\u0644\\\\u0647\\\",\\\"#\\\\u0634\\\\u0644\\\\u0647_\\\\u062f\\\\u0631\\\\u0628\\\\u0627\\\\u0631\\\\u06cc\\\",\\\"#food\\\\u2069\\\"]\"', '\"[\\\"@hadi_sahafian\\\",\\\"@darbari_mashhad\\\"]\"', 8628, 264, 452872, 0, '2025-10-06 04:28:39', NULL, '2025-12-05 12:35:24', '2025-12-05 12:35:24'),
